package com.streak.app
import android.app.*; import android.content.*; import android.os.Build; import androidx.core.app.NotificationCompat; import java.time.LocalDate; import java.time.temporal.ChronoUnit
class ReminderReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){val p=c.getSharedPreferences("streak",Context.MODE_PRIVATE);val s=p.getString("start",LocalDate.now().toString())!!;val d=ChronoUnit.DAYS.between(LocalDate.parse(s),LocalDate.now()).coerceAtLeast(0);val n=c.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager;if(Build.VERSION.SDK_INT>=26)n.createNotificationChannel(NotificationChannel("daily","Daily streak reminder",NotificationManager.IMPORTANCE_DEFAULT));n.notify(830,NotificationCompat.Builder(c,"daily").setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle("Keep your streak going 🔥").setContentText("You're $d days free. Check in today.").setAutoCancel(true).build())}}